export function getBlogBySlug(slug, includeDrafts = false) {
  if (!slug) return null;
  const clean = String(slug).toLowerCase().trim();
  const found = blogs.find((b) => b.slug.toLowerCase() === clean);
  if (!found) return null;
  if (!includeDrafts && found.status === 'draft') return null;
  return found;
}

export function getRelatedBlogs(currentSlug, limit = 3) {
  const current = getBlogBySlug(currentSlug, true);
  const published = blogs.filter((b) => b.status !== 'draft');
  if (!current) return published.slice(0, limit);
  return published
    .filter((b) => b.slug !== current.slug)
    .sort((a, b) => {
      if (a.category === current.category && b.category !== current.category) return -1;
      if (b.category === current.category && a.category !== current.category) return 1;
      return 0;
    })
    .slice(0, limit);
}
